import {UI} from '../shared/copy.js';
import {DESIGN_COPY} from '../shared/design-copy.js';
import {TEMPLATES,validTemplate} from '../shared/templates.js';
import {MENU} from '../shared/menu.js';
import {answerText} from '../shared/chat.js';
import {esc,money,getLang,setLang,languageOptions,LANGS,icon,download} from '../shared/core.js';
import {readState,mutate,menuFor,event,setOrderState,markReviewed,redeemCoupon,posPayload,STORAGE_KEY} from '../shared/state.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');let lang=getLang(),tab=['dashboard','orderInbox','guestLog','storeSetup','connections'].includes(location.hash.slice(1))?location.hash.slice(1):'dashboard',toastTimer,setupStage=1,previews=[],photoNames=[],draft=null;
const t=k=>DESIGN_COPY[lang]?.[k]||UI[lang][k]||k,s=()=>readState();
function toast(v){$('#toast').textContent=v;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3800)}
function safe(fn){try{return fn()}catch(e){toast(t(UI[lang][e.message]?e.message:'storageError'));return null}}
const navItems=[['dashboard','dashboard'],['orderInbox','orders'],['guestLog','chat'],['storeSetup','profile'],['connections','settings']];
function brand(){return `<div class="brand"><img src="assets/brand.png" alt="주모 Jumo"><div><b>${esc(s().store.name)}</b><small>modu ai · 모두의 AI</small></div></div>`}
function nav(mobile=false){return `<nav class="${mobile?'mobile-nav':'side-nav'}" aria-label="${esc(t('owner'))}">${navItems.map(([id,ic])=>`<button class="nav-item ${tab===id?'active':''}" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(ic)}<span>${esc(t(id))}</span></button>`).join('')}</nav>`}
function render(){document.documentElement.lang=lang;app.innerHTML=`<aside class="sidebar">${brand()}${nav()}<div class="side-bottom"><a href="./?lang=${lang}">${esc(t('openGuest'))} ${icon('arrow')}</a><a href="../?lang=${lang}">${esc(t('book'))} ${icon('arrow')}</a><div class="modu-brand">modu ai<span>모두의 AI</span></div></div></aside><main class="page"><header class="topbar"><div class="mobile-brand">${brand()}</div><div class="owner-top-actions"><a class="secondary" href="./?lang=${lang}">${esc(t('openGuest'))}${icon('arrow')}</a><button class="secondary" data-action="export">${esc(t('export'))}</button></div><div class="top-right"><label class="lang-picker">${icon('globe')}<select id="language" aria-label="${esc(t('language'))}">${languageOptions(lang)}</select></label></div></header><div class="demo-bar">${esc(t('ownerNote'))}</div><section id="view">${renderView()}</section></main>${nav(true)}`;if(tab==='storeSetup'&&setupStage===3)renderQr();}
function title(key,desc){return `<div class="section-intro"><h1>${esc(t(key))}</h1>${desc?`<p>${esc(t(desc))}</p>`:''}</div>`}
function renderView(){if(tab==='orderInbox')return inbox();if(tab==='guestLog')return guests();if(tab==='storeSetup')return setup();if(tab==='connections')return connections();return dashboard();}
function sessionLabel(id){const v=s().sessions.find(v=>v.id===id);return v?(v.consent&&v.nickname?v.nickname:t('guest'))+' · '+t('table')+' '+v.table:t('guest')}
function time(v){return new Date(v).toLocaleTimeString(lang,{hour:'2-digit',minute:'2-digit'})}
function activity(e,full=false){return `<article class="activity"><div class="event-icon">${icon(e.type==='eventOrder'?'orders':e.type==='eventGame'?'games':'chat')}</div><div><strong>${esc(t(e.type))}</strong><p>${esc(sessionLabel(e.sessionId))}</p>${e.detail?.question?`<p>“${esc(e.detail.question)}”</p>`:''}${e.detail?.total?`<p>${money(e.detail.total)}</p>`:''}${full&&!e.reviewed&&['complaint','eventStaff'].includes(e.type)?`<button class="text-button" data-review="${e.id}">${esc(t('resolve'))}</button>`:''}${e.reviewed?`<span class="status resolved">${esc(t('resolved'))}</span>`:''}</div><small>${esc(time(e.at))}</small></article>`}
function dashboard(){const st=s(),attention=st.events.filter(e=>['complaint','eventStaff'].includes(e.type)&&!e.reviewed);return `${title('ownerTitle')}<div class="stat-grid">${[['visits',st.sessions.length],['orderCount',st.orders.length],['sales',money(st.orders.reduce((n,o)=>n+o.total,0))],['needsAttention',attention.length]].map(([k,n])=>`<div class="stat"><small>${esc(t(k))}</small><strong>${n}</strong></div>`).join('')}</div><div class="owner-two"><div class="glass"><div class="section-row"><h2>${esc(t('recentActivity'))}</h2><button class="text-button" data-action="refresh" aria-label="${esc(t('refresh'))}">↻</button></div>${st.events.length?st.events.slice(-8).reverse().map(e=>activity(e)).join(''):`<p class="empty">${esc(t('noActivity'))}</p>`}</div><div><div class="glass"><h2>${esc(t('needsAttention'))}</h2>${attention.length?attention.slice(-8).reverse().map(e=>activity(e,true)).join(''):`<p class="empty">${esc(t('noActivity'))}</p>`}</div><div class="glass" style="margin-top:24px"><span class="pill">modu ai · 모두의 AI</span><h3 style="margin-top:18px">${esc(t('subscription'))}</h3><p class="small">${esc(t('subscriptionNote'))}</p><a class="text-button" href="../?lang=${lang}#business">${esc(t('book'))} ${icon('arrow')}</a></div></div></div>`}
function inbox(){const st=s();return `${title('orderInbox','noRealPayment')}<div class="inbox-grid">${st.orders.length?[...st.orders].reverse().map(o=>{const next={pending:['accepted','accept'],accepted:['preparing','prepare'],preparing:['ready','ready'],ready:['completed','serve']}[o.status];return `<article class="glass order-card"><div class="order-header"><div><h3>#${String(o.number).padStart(3,'0')} · ${esc(t('table'))} ${o.table}</h3><small>${esc(time(o.at))} · ${esc(LANGS[o.lang])}</small></div><span class="status ${o.status}">${esc(t(o.status))}</span></div>${o.lines.map(l=>`<div class="order-item"><span>${esc(MENU.find(x=>x.id===l.itemId)?.name[lang]||l.itemId)} × ${l.quantity}</span><b>${money(l.quantity*l.unitPrice)}</b></div>`).join('')}<div class="order-summary"><span>${esc(t('total'))}</span><strong>${money(o.total)}</strong></div><div class="order-statuses"><span>${esc(t('payment'))}</span><span class="status ${o.payment}">${esc(t(o.payment))}</span></div><div class="form-actions">${next?`<button class="primary" data-order="${o.id}" data-next="${next[0]}">${esc(t(next[1]))}</button>`:''}${o.payment!=='paid'?`<button class="secondary" data-pay="${o.id}">${esc(t('markPaid'))}</button>`:''}</div></article>`}).join(''):`<div class="glass empty">${esc(t('emptyOrders'))}<br><a class="text-button" href="./?lang=${lang}">${esc(t('openGuest'))}</a></div>`}</div>`}
function guests(){const st=s();return `${title('guestLog','memberNotice')}<div class="glass"><h2>${esc(t('allSessions'))}</h2>${st.sessions.length?[...st.sessions].reverse().map(v=>`<article class="guest-record"><div><h3>${esc(v.consent&&v.nickname?v.nickname:t('guest'))}</h3><p>${esc(t('table'))} ${v.table} · ${esc(LANGS[v.lang])} · ${esc(time(v.at))}</p><p>${esc(t('conversation'))}: ${v.messages.length} · ${esc(t('orders'))}: ${st.orders.filter(o=>o.sessionId===v.id).length}</p>${v.coupons.map(c=>`<div class="coupon"><div><b>${esc(t(c.reward))}</b><p><code>${esc(c.code)}</code></p></div>${c.used?`<span class="status completed">${esc(t('couponUsed'))}</span>`:`<button class="secondary" data-redeem="${c.id}" data-session="${v.id}">${esc(t('redeem'))}</button>`}</div>`).join('')}</div><button class="secondary" data-session-log="${v.id}">${esc(t('viewConversation'))}</button></article>`).join(''):`<p class="empty">${esc(t('noActivity'))}</p>`}</div>`}
function sessionLog(id){const v=s().sessions.find(x=>x.id===id);if(!v)return;modal.innerHTML=`<div class="modal-head"><h2>${esc(sessionLabel(id))}</h2><button class="icon-button" data-action="close" aria-label="${esc(t('close'))}">${icon('close')}</button></div><div class="modal-body"><p class="caption">${esc(t('localOnly'))}</p>${v.messages.length?v.messages.map(m=>`<div class="glass" style="padding:18px;margin-bottom:14px"><small>${esc(LANGS[m.lang])} · ${esc(time(m.at))}</small><p style="color:var(--text);margin:10px 0">${esc(m.text)}</p><p class="small">${esc(t('reply'))}: ${esc(answerText(m,m.lang))}</p></div>`).join(''):`<p class="empty">${esc(t('noMessages'))}</p>`}<h3>${esc(t('needsAttention'))}</h3>${s().events.filter(e=>e.sessionId===id&&['complaint','eventStaff'].includes(e.type)).map(e=>activity(e,true)).join('')}</div>`;if(!modal.open)modal.showModal();}
function setup(){const st=s(),store=draft||st.store;if(setupStage===3)return `${title('storeCreated')}<div id="qr-print-section" class="glass qr-layout"><div><h2>${esc(t('qrTitle'))}</h2><p>${esc(t('qrNote'))}</p><label>${esc(t('table'))}<input id="qr-table" type="number" min="1" max="999" value="3"></label><a id="guest-link" class="link-field" href="./?lang=${lang}&table=3"></a><div class="form-actions"><button class="primary" data-action="copy-qr">${esc(t('copyLink'))}</button><button class="secondary" data-action="print-qr">${esc(t('printQr'))}</button><button class="secondary" data-action="download-qr">${esc(t('downloadQr'))}</button><button class="text-button" data-action="edit-store">${esc(t('back'))}</button></div></div><div class="qr-paper"><img class="logo" src="assets/brand.png" alt="주모"><h3>${esc(st.store.name)}</h3><p>${esc(t('table'))} <b id="qr-number">03</b></p><div class="qr-code" id="qr-code"></div><p>${esc(t('menu'))} · ${esc(t('chat'))}</p><small>${esc(t('demoNote'))}</small><p class="modu-brand">modu ai <span>모두의 AI</span></p></div></div>`;
if(setupStage===2)return `${title('reviewMenu','reviewNote')}<form id="review-form" class="glass">${menuFor(st).map(x=>`<div class="review-row"><b>${esc(x.name[lang])}</b><input name="price-${x.id}" type="number" min="1000" max="9999000" step="1000" required value="${x.price}" aria-label="${esc(x.name[lang])} ${esc(t('price'))}"><label><input type="checkbox" name="available-${x.id}" ${x.available?'checked':''}>${esc(t('available'))}</label></div>`).join('')}<p class="caption">${esc(t('priceNote'))}</p><label class="check-row"><input type="checkbox" name="approved" required><span>${esc(t('approveMenu'))}</span></label><div class="form-actions"><button type="button" class="secondary" data-action="edit-store">${esc(t('back'))}</button><button class="primary">${esc(t('createStore'))}</button></div></form>`;
return `${title('storeSetup','reviewNote')}${designGallery()}<form id="store-form" class="glass"><div class="form-grid"><label>${esc(t('storeName'))} · ${esc(t('required'))}<input name="name" value="${esc(store.name)}" required maxlength="50" autocomplete="organization"></label><label>${esc(t('country'))}<select name="country">${[['VN','Việt Nam'],['KR','대한민국'],['OTHER','Other']].map(([v,l])=>`<option value="${v}" ${store.country===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="span-2">${esc(t('address'))} · ${esc(t('required'))}<input name="address" value="${esc(store.address)}" required maxlength="200" autocomplete="street-address"></label><label>${esc(t('phone'))}<input type="tel" name="phone" value="${esc(store.phone)}" maxlength="35"></label><label>${esc(t('email'))}<input type="email" name="email" value="${esc(store.email)}" maxlength="150"></label><label class="span-2">${esc(t('website'))}<input type="url" name="website" value="${esc(store.website)}" placeholder="https://…" maxlength="250"></label></div><div class="upload-area"><label for="photos">${esc(t('upload'))}</label><input id="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><p class="caption">${esc(t('uploadNote'))}</p><div class="photo-previews" id="photo-previews">${previews.map(url=>`<img src="${url}" alt="${esc(t('upload'))}">`).join('')}</div><p class="caption" id="photo-status">${photoNames.length?`${esc(t('photoCount'))}: ${photoNames.length}`:''}</p></div><div class="form-actions"><button class="primary">${esc(t('reviewMenu'))}${icon('arrow')}</button><button type="button" class="text-button" data-action="existing-qr">${esc(t('qrTitle'))}</button></div></form>`}
function designGallery(){const current=validTemplate(s().store.template);return `<section class="design-section"><div class="section-row"><h2>${esc(t('designTemplates'))}</h2><span class="pill">05</span></div><p>${esc(t('templateNote'))}</p><div class="template-gallery">${TEMPLATES.map((x,i)=>`<article class="template-card ${current===x.id?'is-selected':''}"><button class="template-mini mini-${x.id}" data-preview="${x.id}" style="--mini-accent:${x.color};--mini-bg:${x.background}" aria-label="${esc(t(x.name))} ${esc(t('preview'))}"><span class="mini-top"><b>주모</b><i>Jumo</i></span><strong>${esc(t('menuHeadline'))}</strong><span class="mini-search"></span><span class="mini-categories"><i></i><i></i><i></i><i></i></span><span class="mini-hero"><img src="assets/jeon.jpg" alt=""><b>Jumo<br>signature.</b></span><span class="mini-cards"><img src="assets/kimchi.jpg" alt=""><img src="assets/samhap.jpg" alt=""></span><span class="mini-nav">${icon('menu')}${icon('chat')}${icon('games')}${icon('orders')}</span></button><div class="template-info"><span class="template-number">0${i+1}</span><h3>${esc(t(x.name))}</h3><p>${esc(t(x.description))}</p><div class="template-actions"><button class="secondary" data-preview="${x.id}">${esc(t('preview'))}</button><button class="primary" data-template="${x.id}" ${current===x.id?'disabled':''}>${current===x.id?icon('check'):''}${esc(t(current===x.id?'applied':'apply'))}</button></div></div></article>`).join('')}</div></section>`}
function previewDesign(id){id=validTemplate(id);const item=TEMPLATES.find(x=>x.id===id);modal.classList.add('design-preview-dialog');modal.innerHTML=`<div class="modal-head"><h2>${esc(t(item.name))}</h2><button class="icon-button" data-action="close" aria-label="${esc(t('close'))}">${icon('close')}</button></div><div class="preview-phone"><iframe src="./?lang=${lang}&template=${id}&preview=1" title="${esc(t(item.name))} ${esc(t('preview'))}"></iframe></div><div class="modal-head"><small>${esc(t('previewOnly'))}</small><button class="primary" data-template="${id}">${esc(t('apply'))}</button></div>`;modal.showModal();}
function connections(){const st=s();return `${title('connections')}<div class="owner-two"><div class="glass"><span class="status">${esc(t('notConnected'))}</span><h2 style="margin-top:18px">${esc(t('posTitle'))}</h2><p>${esc(t('posNote'))}</p><div class="endpoint"><span class="route-method">POST</span>/v1/orders</div><div class="endpoint"><span class="route-method">POST</span>/v1/webhooks/pos</div><div class="endpoint"><span class="route-method">GET</span>/v1/orders/{orderId}</div><pre class="code-box">${esc(JSON.stringify(posPayload(st),null,2))}</pre><div class="form-actions"><button class="secondary" data-action="export-pos">${esc(t('posExport'))}</button><a class="text-button" href="../api/pos-contract.json" target="_blank" rel="noopener">${esc(t('apiContract'))} ${icon('arrow')}</a></div></div><div><form id="budget-form" class="glass"><h2>${esc(t('budgetTitle'))}</h2><p>${esc(t('budgetNote'))}</p><div class="form-grid"><label>${esc(t('perVisit'))}<input name="perVisit" type="number" min="1" max="100" value="${st.store.perVisit}" required></label><label>${esc(t('perDay'))}<input name="perDay" type="number" min="1" max="10000" value="${st.store.perDay}" required></label></div><div class="form-actions"><button class="primary">${esc(t('save'))}</button></div></form><div class="glass" style="margin-top:24px"><h3>${esc(t('scopeNote'))}</h3><p>${esc(t('offTopic'))}</p><p class="caption">${esc(t('demoNote'))}</p></div></div></div>`}
function qrUrl(){const number=Math.min(999,Math.max(1,parseInt($('#qr-table')?.value,10)||3));return new URL(`./?lang=${lang}&table=${number}`,location.href).href}
function renderQr(){const code=globalThis.qrcode(0,'M');code.addData(qrUrl());code.make();$('#qr-code').innerHTML=code.createSvgTag({cellSize:5,margin:4,scalable:true});$('#qr-code svg').setAttribute('aria-label',t('qrTitle'));$('#qr-code svg').setAttribute('role','img');$('#guest-link').textContent=qrUrl();$('#guest-link').href=qrUrl();$('#qr-number').textContent=String(new URL(qrUrl()).searchParams.get('table')).padStart(2,'0')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.preview){previewDesign(b.dataset.preview);return;}if(b.dataset.template){const id=validTemplate(b.dataset.template);const ok=safe(()=>mutate(st=>{st.store.template=id;return true}));if(ok){if(draft)draft.template=id;if(modal.open)modal.close();modal.classList.remove('design-preview-dialog');render();toast(t('designSaved'));}return;}if(b.dataset.tab){tab=b.dataset.tab;history.replaceState(null,'','#'+tab);render();window.scrollTo({top:0,behavior:'instant'});return;}if(b.dataset.order){safe(()=>setOrderState(b.dataset.order,b.dataset.next));render();return;}if(b.dataset.pay){safe(()=>setOrderState(b.dataset.pay,'paid',true));render();toast(t('noRealPayment'));return;}if(b.dataset.review){safe(()=>markReviewed(b.dataset.review));if(modal.open)modal.close();render();return;}if(b.dataset.sessionLog){sessionLog(b.dataset.sessionLog);return;}if(b.dataset.redeem){safe(()=>redeemCoupon(b.dataset.session,b.dataset.redeem));render();return;}switch(b.dataset.action){case 'close':modal.close();modal.classList.remove('design-preview-dialog');break;case 'refresh':render();break;case 'export':download('modu-ai-jumo-demo-records.json',JSON.stringify(s(),null,2));break;case 'export-pos':download('jumo-pos-example.json',JSON.stringify(posPayload(s()),null,2));break;case 'existing-qr':setupStage=3;render();break;case 'edit-store':setupStage=1;render();break;case 'copy-qr':try{await navigator.clipboard.writeText(qrUrl());toast(t('copied'))}catch{toast(t('copyFailed'))}break;case 'download-qr':download('jumo-table-'+new URL(qrUrl()).searchParams.get('table')+'.svg',$('#qr-code svg').outerHTML,'image/svg+xml');break;case 'print-qr':{location.href=`print.html?lang=${lang}&table=${new URL(qrUrl()).searchParams.get('table')}`;break;}}});
document.addEventListener('change',e=>{if(e.target.id==='language'){lang=e.target.value;setLang(lang);render()}if(e.target.id==='photos'){const files=[...e.target.files];if(files.length>3||files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024)){toast(t('uploadError'));e.target.value='';return;}previews.forEach(URL.revokeObjectURL);previews=files.map(f=>URL.createObjectURL(f));photoNames=files.map(f=>f.name);$('#photo-previews').innerHTML=previews.map(url=>`<img src="${url}" alt="${esc(t('upload'))}">`).join('');$('#photo-status').textContent=t('photoCount')+': '+files.length;}if(e.target.id==='qr-table')renderQr();});
document.addEventListener('input',e=>{if(e.target.id==='qr-table')renderQr()});
document.addEventListener('submit',e=>{if(e.target.id==='store-form'){e.preventDefault();const data=new FormData(e.target);draft={...s().store,...Object.fromEntries(data),photos:photoNames};setupStage=2;render();}if(e.target.id==='review-form'){e.preventDefault();const data=new FormData(e.target);if(!data.has('approved')){toast(t('approvalRequired'));return;}const ok=safe(()=>mutate(st=>{st.store={...st.store,...draft};for(const x of MENU){const price=Number(data.get('price-'+x.id));if(!Number.isInteger(price)||price<1000||price>9999000)throw new Error('approvalRequired');st.menu[x.id]={price,available:data.has('available-'+x.id)}}event(st,'eventStore',null,{name:st.store.name});return true}));if(ok){setupStage=3;draft=null;render();toast(t('saved'));}}if(e.target.id==='budget-form'){e.preventDefault();const data=new FormData(e.target),perVisit=Number(data.get('perVisit')),perDay=Number(data.get('perDay'));if(!Number.isInteger(perVisit)||perVisit<1||perVisit>100||!Number.isInteger(perDay)||perDay<1||perDay>10000)return;safe(()=>mutate(st=>{st.store.perVisit=perVisit;st.store.perDay=perDay}));toast(t('saved'));}});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY&&tab!=='storeSetup'&&tab!=='connections')render()});
render();
